plain=[{'poem_id': 455, 'rationale': 'The repeated testimony of violence against girls remains text-led, consistent with its December appearance; no fabricated victim or emergency scene.', 'status': 'pending'}, {'poem_id': 459, 'rationale': 'This personal address to Jamie names a particular bond and anniversary. Let those words carry the memorial without an invented likeness or generic heaven imagery.', 'status': 'pending'}, {'poem_id': 460, 'rationale': 'The intimate account of power, injury and longing should not be prettified as a romantic paper boat; retain the speaker’s complex voice in a text-led opening.', 'status': 'pending'}]
for p in (S/'content/editions/issue-23').glob('poem-*.json'):(B/p.name).write_bytes(p.read_bytes())
